package dev.packsmith.mt; import bin.mt.plugin.api.editor.TextEditor; import bin.mt.plugin.api.ui.PluginUI; public class GenerateBlockMenu extends CompatMenuBase { public String name(){return "Generate block JSON";} protected String iconName(){return "block";} public void onMenuClick(PluginUI ui,TextEditor e){String id=selectedId(e,"example");EditorUtil.replaceWhole(e,TemplateUtil.block(ctx(),id));ui.showToast("Generated for "+id);} }